"""Cuaderno del estudiante, 7.º básico Lengua y Literatura, OA 17 (correferencia léxica y cohesión).

Textos originales y breves; cada ejercicio trae el texto que necesita.
Aquí se definen también los ayudantes `L`, `E`, `task`, `n_words`, `cnt` que reutilizan los otros módulos le7_c*.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA17 = "LE07 OA 17"
E = ex


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


def n_words(text):
    """Cuenta las palabras de un texto separado por espacios (los signos no cuentan como palabras)."""
    return str(len(text.split()))


def cnt(text, sign):
    """Cuenta cuántas veces aparece una cadena en un texto."""
    return str(text.count(sign))


MAT = "Este cuaderno, lápiz y los textos escritos en cada ejercicio. Si quieres, lápices de dos colores para subrayar."

# ------------------------------------------------------------------ OA 17
L(OA17, 1,
  MAT,
  "Aprenderé a reconocer a qué persona, cosa o idea se refiere un texto (el referente) y a decidir cuándo una repetición ayuda y cuándo sobra.",
  ["Sé qué es un sustantivo y un pronombre.", "Reconozco el tema de un párrafo."],
  ["Todo texto habla de algo o de alguien: ese algo es el referente. Un referente puede nombrarse muchas veces: «la directora», «ella», «la autoridad». Cuando varias expresiones apuntan al mismo referente, decimos que hay correferencia. Gracias a ella un párrafo se lee como un todo y no como oraciones sueltas.",
   "La forma más simple de mantener el referente es repetir la misma palabra. A veces la repetición es útil: evita confusiones cuando hay dos referentes parecidos («la bomba A» y «la bomba B») o cuando se usa un término técnico que no debe cambiar. Otras veces sobra: si la misma palabra abre tres oraciones seguidas y no hay nada que aclarar, el texto suena pesado.",
   "Para revisar un texto, primero subraya cada vez que aparece el referente. Luego pregúntate dos cosas: ¿quedaría confuso si lo cambio? y ¿suena pesado si lo repito? Si cambiarlo confunde, conserva la repetición. Si solo suena pesado, busca otra manera de nombrarlo, tema que veremos en las próximas clases."],
  [("referente", "persona, cosa o idea de la que habla el texto"), ("correferencia", "relación entre expresiones distintas que nombran el mismo referente"), ("cohesión", "unión de las partes de un texto mediante recursos del lenguaje"), ("ambigüedad", "cuando una expresión puede entenderse de dos maneras")],
  [("Subrayar el referente", "En «La brigada de reciclaje armó un punto limpio. La brigada pesó el papel y anotó los kilos.», ¿cuál es el referente y cuántas veces se nombra con las mismas palabras?",
    ["Veo de quién se habla: de la brigada.", "Busco «La brigada»: aparece al comienzo de cada oración.", "Cuento: son dos veces nombrada igual."],
    "«La brigada de reciclaje»; se repite «La brigada» 2 veces"),
   ("Repetición necesaria", "En «Se probó la batería A y la batería B. La batería B duró más.», ¿es útil repetir «batería B»?",
    ["Hay dos referentes parecidos: A y B.", "Si escribo solo «La batería duró más», no se sabría cuál.", "La repetición con la letra evita la confusión."],
    "Sí, es útil porque distingue entre dos baterías")],
  [("Pensar que toda repetición es un error.", "Se cree que un buen texto nunca repite palabras.", "Repite cuando evita confusión o cuando el término técnico no debe cambiar."),
   ("Cambiar una palabra solo por «no repetir», sin fijarse en qué referente nombra.", "Se confunden dos referentes parecidos.", "Antes de cambiar una palabra, comprueba que siga nombrando el mismo referente.")],
  ([E("En «Matilde guardó la bicicleta. La bicicleta tenía una rueda rota.», ¿qué palabra se repite?", "bicicleta", "Aparece al final de la primera oración y al comienzo de la segunda."),
    E("En «Ayer, Inés trajo la tarea. Ella la entregó temprano.», ¿a quién se refiere «Ella»?", "A Inés", "Es la única persona nombrada antes de «Ella»."),
    E("¿Cuántas veces aparece «afiche» en «El afiche quedó listo. Pegamos el afiche en el muro y el afiche se veía bien.»?", cnt("El afiche quedó listo. Pegamos el afiche en el muro y el afiche se veía bien.", "afiche"), "Se cuenta cada aparición de la palabra: tres en total.")],
   [E("En «Los pumas cazan de noche. Los pumas duermen de día.», ¿cuál es el referente que se nombra dos veces igual?", "Los pumas", "Las dos oraciones hablan de ese mismo animal."),
    E("En «Se revisó la bomba A y la bomba B. La bomba falló.», ¿se entiende cuál bomba falló?", "No", "Falta la letra, y puede ser A o B."),
    E("«La feria abrió temprano. La feria vendió verduras. La feria cerró a las 14:00.» Hay un solo referente y nada que aclarar. ¿La repetición de «La feria» es útil o sobra?", "Sobra", "No evita ninguna confusión y vuelve pesado el texto.")],
   [E("¿Cuántas veces se repite «La directora» en «La directora anunció la feria. La directora dijo que será el viernes. La directora pidió ayuda.»?", "3", "Abre las tres oraciones."),
    E("En «Tomás encontró la llave y la guardó en el bolsillo.», ¿qué palabra evita repetir «llave» en la segunda parte?", "la", "Ese pronombre toma el lugar de «la llave»."),
    E("Texto 1: «Mezcla la pintura roja con la pintura azul.» Texto 2: «Salió el sol. El sol brilló. El sol calentó.» ¿En cuál repetir es necesario para distinguir?", "En el texto 1", "Hay dos pinturas distintas y los colores las diferencian.")],
   [E("Versión 1: «Ana y Beatriz armaron dos maquetas. La maqueta pesa más.» Versión 2: «Ana y Beatriz armaron dos maquetas. La maqueta de Ana pesa más.» ¿Cuál versión se entiende con claridad?", "La versión 2", "Dice de quién es la maqueta más pesada."),
    E("«Mezcle la sustancia A con la sustancia B. Luego agregue el producto.» Quien escribe quería decir «la sustancia B». ¿Qué problema tiene «el producto»?", "No queda claro si es la sustancia B o la mezcla", "La nueva expresión puede nombrar dos cosas distintas.")],
   [E("¿Cuántas palabras se repiten idénticas en las tres oraciones «La brigada reunió 12 kilos de papel.», «La brigada reunió 8 kilos de cartón.» y «La brigada reunió 5 kilos de plástico.»? Cuenta «La brigada reunió» y «kilos de».", "5", "Son La, brigada, reunió, kilos y de; cambian el número y el material."),
    E("«Sofía y Lucía llevaron un cuaderno cada una. El cuaderno de Sofía era azul. El cuaderno era de tapa dura.» ¿A qué cuaderno se refiere la última oración?", "No se puede saber", "Podría ser el de Sofía o el de Lucía.")]),
  [E("En un cartel dice: «La ruta 1 pasa por el parque. La ruta 2 pasa por la costanera. La ruta es más larga.» ¿Se entiende cuál ruta es la más larga?", "No", "Falta el número de la ruta en la última oración.")],
  [E("¿Cómo se llama la persona, cosa o idea de la que habla un texto?", "Referente", "Es lo que las distintas expresiones nombran."),
   E("¿Cuándo es útil repetir una palabra: cuando evita una confusión o cuando suena bonito?", "Cuando evita una confusión", "La repetición necesaria mantiene el referente claro."),
   E("Si dos expresiones distintas nombran lo mismo, ¿hay correferencia o ambigüedad?", "Correferencia", "La ambigüedad sería que pudieran entenderse de dos modos.")],
  ("Lee este texto: «El huerto escolar tiene dos camas: la cama norte y la cama sur. La cama norte recibe sol de mañana. La cama norte tiene lechugas. La cama norte se riega los lunes. La cama sur tiene zanahorias. La cama se riega los jueves.» 1) Subraya cada vez que aparece «la cama norte». 2) Di qué repeticiones sobran. 3) Encuentra la oración ambigua y arréglala.",
   "Subrayo «la cama norte» cuatro veces: una en la primera oración y tres seguidas después. Sobran las repeticiones de la tercera y cuarta oración si cambio la forma de nombrarla. La oración ambigua es la última: «La cama se riega los jueves» no dice si es la norte o la sur; la arreglo con «La cama sur se riega los jueves».",
   ["encuentra todas las apariciones del referente", "distingue repetición que sobra de repetición necesaria", "detecta la oración ambigua y la corrige sin cambiar el sentido"], ["texto subrayado", "oración corregida"], ["tachar «norte» y «sur» y dejar solo «la cama»", "no ver que la última oración es ambigua"], "Pide a otra persona que lea tu versión y diga a qué cama se refiere cada oración."),
  "Busca en una cajita de cereal o en un aviso de tu casa un texto corto y subraya el referente principal cada vez que aparece.",
  "Escribe tres oraciones sobre dos mascotas imaginarias donde repetir el nombre sea necesario, y explica por qué.")

L(OA17, 2,
  MAT,
  "Aprenderé a reemplazar una palabra repetida por otra que nombre el mismo referente sin cambiar el significado ni crear confusión.",
  ["Reconozco el referente de un texto.", "Sé cuándo una repetición es útil."],
  ["La sustitución léxica consiste en reemplazar una palabra por otra que nombra el mismo referente. Puede hacerse con un sinónimo («casa» por «vivienda»), con una palabra más general («el perro» por «el animal») o con una expresión que describe («Valparaíso» por «el puerto»). El texto se vuelve más variado sin perder su hilo.",
   "Sustituir con precisión exige comprobar tres cosas. Primero, que la nueva expresión nombre el mismo referente. Segundo, que no agregue datos falsos: «la niña» no sirve para reemplazar a «la ministra» si se trata de una adulta. Tercero, que el lector entienda de inmediato a quién o a qué se refiere. Si dudas, vuelve a la palabra original.",
   "Una buena prueba es leer la oración con y sin el cambio. Si el significado es el mismo y no hay otra posible lectura, la sustitución funciona. Si aparecen dos lecturas posibles o se pierde un dato importante, la sustitución falla. Recuerda: sustituir no es adornar, es ayudar a leer."],
  [("sustitución léxica", "reemplazo de una palabra por otra que nombra el mismo referente"), ("sinónimo", "palabra de significado cercano a otra"), ("expresión descriptiva", "grupo de palabras que describe al referente, como «el puerto»"), ("precisión", "ajuste exacto de una palabra a lo que se quiere decir")],
  [("Sustitución adecuada", "En «La ministra visitó la escuela. La ministra habló con los docentes.», ¿qué expresión puede reemplazar a la segunda «La ministra»?",
    ["Busco algo que nombre a la misma persona.", "«La autoridad» sirve: es una expresión más general y la visita es de una persona con un cargo.", "«La niña» no sirve: cambia la edad y el dato."],
    "«La autoridad»"),
   ("Sustitución que confunde", "En «Pedro y Mateo armaron un cohete. Pedro lo lanzó.», ¿sirve cambiar «Pedro» por «el niño»?",
    ["Hay dos niños en el texto.", "«El niño» podría ser Pedro o Mateo.", "El cambio crea ambigüedad."],
    "No sirve: no se sabe de cuál niño se habla")],
  [("Reemplazar por una palabra que parece parecida pero cambia el dato.", "Se escoge «la niña» para nombrar a una ministra.", "Comprueba que la palabra nueva describa bien al mismo referente."),
   ("Sustituir cuando hay dos referentes parecidos.", "Se cambia el nombre por «el niño» o «la máquina».", "Si hay dos posibles, deja el nombre propio o añade un dato que los distinga.")],
  ([E("En «El perro ladró. El animal corrió hacia la puerta.», ¿qué expresión sustituyó a «El perro»?", "El animal", "Nombra al mismo perro con una palabra más general."),
    E("¿Cuál sirve para reemplazar «vivienda» sin cambiar el sentido: «casa» o «jardín»?", "Casa", "Una vivienda es un lugar donde se vive, igual que una casa."),
    E("En «Valparaíso recibió turistas. El puerto estaba lleno.», ¿qué expresión sustituye a «Valparaíso»?", "El puerto", "Nombra a la misma ciudad con una descripción.")],
   [E("«El bus llegó atrasado. El vehículo traía 30 pasajeros.» ¿«El vehículo» nombra el mismo referente que «El bus»?", "Sí", "Un bus es un vehículo, y no hay otro vehículo en el texto."),
    E("«La ministra visitó la escuela. La niña saludó a los docentes.» ¿«La niña» es una sustitución adecuada para «La ministra»?", "No", "Una ministra es una adulta; «la niña» cambia el dato."),
    E("«Lucía y Rosa pintaron un mural. La joven usó azul.» ¿Se entiende de quién se habla en la segunda oración?", "No", "«La joven» puede ser Lucía o Rosa.")],
   [E("Reemplaza la segunda repetición: «El cóndor sobrevoló el valle. El cóndor descendió despacio.» ¿Cuál de estas expresiones sirve: «el ave» o «el valle»?", "El ave", "El cóndor es un ave; el valle es otro referente."),
    E("«El Estadio Nacional abrió sus puertas. El recinto recibió a miles de personas.» ¿Qué expresión sustituye a «El Estadio Nacional»?", "El recinto", "Nombra al estadio con una palabra distinta."),
    E("«Camila ganó el premio. La campeona agradeció.» ¿«La campeona» nombra a Camila sin crear confusión?", "Sí", "Solo Camila ganó el premio, así que la expresión apunta a ella.")],
   [E("En «El joven puso la taza sobre la mesa. Luego limpió la mesa.», un lector cambia la segunda «la mesa» por «el vehículo». ¿Por qué falla?", "Porque «el vehículo» no nombra la mesa", "La sustitución debe nombrar el mismo referente."),
    E("«Martín, de 12 años, y su tío visitaron el museo. El adulto sacó fotos.» ¿«El adulto» nombra a Martín?", "No", "Martín tiene 12 años; el adulto es el tío.")],
   [E("En «El gato negro saltó a la repisa. El felino tiró un florero y el animal huyó.», ¿cuántas expresiones distintas nombran al gato además de «El gato negro»?", "2", "Son «El felino» y «el animal»."),
    E("«El profesor Ortiz y el profesor Vega revisaron el informe. El docente lo aprobó.» ¿Se entiende quién lo aprobó?", "No", "«El docente» puede nombrar a cualquiera de los dos profesores.")]),
  [E("Un cartel de la biblioteca dice: «Cada persona puede llevar un libro por 7 días. El ejemplar puede renovarse una vez.» ¿Qué dos expresiones nombran lo mismo?", "un libro y el ejemplar", "Ambas se refieren al libro que se lleva.")],
  [E("¿Qué se hace en una sustitución léxica: se cambia una palabra por otra del mismo referente o se borra la oración?", "Se cambia una palabra por otra del mismo referente", "La sustitución mantiene el referente."),
   E("Si una sustitución puede entenderse de dos maneras, ¿tiene ambigüedad o precisión?", "Ambigüedad", "El lector no sabe a cuál referente apunta."),
   E("¿«Vivienda» es un sinónimo de «casa» o de «calle»?", "De casa", "Ambas nombran el lugar donde se vive.")],
  ("Reescribe este texto cambiando tres repeticiones por sustituciones léxicas precisas: «El alcalde inauguró la plaza. El alcalde cortó la cinta. La plaza tiene juegos y la plaza tiene árboles. El alcalde dijo que la plaza será de todos». Luego explica por qué cada cambio no confunde.",
   "El alcalde inauguró la plaza. La autoridad cortó la cinta. El espacio tiene juegos y árboles. Dijo que el lugar será de todos. «La autoridad» nombra al alcalde, y no hay otra autoridad en el texto; «el espacio» y «el lugar» nombran la plaza.",
   ["cambia tres repeticiones", "cada cambio nombra el mismo referente", "explica por qué no hay confusión"], ["texto reescrito", "una frase de justificación por cambio"], ["usar una palabra que nombra a otro referente", "cambiar tanto que se pierde el dato"], "Pide a otra persona que lea tu versión y diga qué nombra cada expresión; si dice algo distinto, ajusta."),
  "Elige un animal que te guste y escribe cuatro maneras de nombrarlo sin repetir su nombre.",
  "Inventa un texto de tres oraciones sobre tu comuna y sustituye al menos dos repeticiones con expresiones distintas.")

L(OA17, 3,
  MAT,
  "Aprenderé a escoger sinónimos que calcen con el contexto, porque dos palabras de significado cercano no siempre se pueden intercambiar.",
  ["Sé qué es un sinónimo.", "Sé sustituir palabras sin cambiar el referente."],
  ["Los sinónimos son palabras de significado cercano, pero casi nunca idénticas. «Caliente» y «cálido» se parecen, y sin embargo decimos «sopa caliente», «clima cálido» y «bienvenida cálida», no al revés. Cada palabra tiene combinaciones habituales y un matiz propio que se llama connotación.",
   "Para escoger un sinónimo, mira cuatro pistas: el significado exacto en esa oración, las palabras que lo acompañan, el registro (más formal o más cotidiano) y el tono. «Niño», «chico» e «infante» nombran lo mismo, pero «infante» suena formal, y «chico», coloquial. En un informe escolar suele convenir el registro formal.",
   "Una palabra puede tener varios sinónimos según el sentido. «Grave» sirve para «herida grave» (seria) pero no para «voz grave» (de tono bajo, sinónimo de «profunda»). Por eso un diccionario de sinónimos se usa con cuidado: se elige la opción cuyo sentido calza con la oración, y se lee de nuevo para comprobar."],
  [("connotación", "matiz o sentimiento que una palabra agrega además de su significado"), ("registro", "forma de hablar según la situación, formal o cotidiana"), ("colocación", "combinación habitual entre palabras, como «clima cálido»"), ("sentido", "significado que una palabra tiene en una oración concreta")],
  [("Elegir según la colocación", "¿Cuál va mejor en «El té está ___»: «caliente» o «cálido»?",
    ["Pienso en lo que se dice habitualmente de un té.", "Decimos «té caliente».", "«Cálido» se usa para climas o ambientes."],
    "Caliente"),
   ("Elegir según el registro", "En un informe de ciencias, ¿conviene escribir «los chicos midieron» o «los estudiantes midieron»?",
    ["Reviso el tipo de texto: un informe formal.", "«Chicos» es cotidiano; «estudiantes» es más formal.", "Elijo el registro del informe."],
    "Los estudiantes midieron")],
  [("Usar el primer sinónimo que aparece.", "Se cree que todos los sinónimos sirven en cualquier oración.", "Comprueba el sentido, las palabras vecinas y el registro."),
   ("Cambiar una palabra técnica por un sinónimo común.", "Se piensa que sirve igual.", "Los términos técnicos suelen mantenerse sin cambio.")],
  ([E("¿Cuál es un sinónimo de «enorme»: «gigante» o «pequeño»?", "Gigante", "Ambas palabras dicen que algo es muy grande."),
    E("¿Qué palabra va con «sopa»: «caliente» o «cálida»?", "Caliente", "Esa es la combinación habitual."),
    E("¿Cuál es más formal: «niño» o «chico»?", "Niño", "«Chico» es más coloquial.")],
   [E("En «La noticia fue ___ para toda la comunidad», ¿qué sinónimo de «importante» calza mejor: «relevante» o «común»?", "Relevante", "Significa que importa mucho, igual que «importante»."),
    E("«Casa» y «vivienda» nombran lo mismo. ¿Cuál se usa con más frecuencia en un documento oficial?", "Vivienda", "Es el término formal."),
    E("¿«Grave» como en «voz grave» es sinónimo de «seria» o de «profunda»?", "Profunda", "Se refiere al tono bajo de la voz, no a la importancia.")],
   [E("«El examen fue difícil» y «El examen fue complicado». ¿Se mantiene el mismo sentido?", "Sí", "Ambos dicen que el examen costó resolverlo."),
    E("«Esa herida es grave» y «Esa herida es seria». ¿Se mantiene el mismo sentido?", "Sí", "En este contexto ambas dicen que la herida es importante."),
    E("En «Recibimos a los invitados con una bienvenida ___», ¿cuál va: «cálida» o «caliente»?", "Cálida", "Se dice bienvenida cálida por costumbre del idioma.")],
   [E("Un informe dice «Los participantes anotaron los datos». Un lector lo cambia por «Los cabros anotaron los datos». ¿Qué se pierde: el significado o el registro formal?", "El registro formal", "El referente es el mismo, pero «cabros» es coloquial."),
    E("Al revisar, dos estudiantes dudan entre «cerca» y «próximo». Una frase dice «la casa próxima a la escuela». ¿Es aceptable?", "Sí", "«Próximo» es más formal y se usa en «próximo a».")],
   [E("En «El perro es muy rápido», ¿cuál de estos reemplazos de «rápido» mantiene el sentido: «veloz» o «alto»?", "Veloz", "Veloz significa que se mueve a gran velocidad."),
    E("Si «bello» y «hermoso» son sinónimos, ¿cuántos sinónimos de «bonito» aparecen en: «Un paisaje bello, hermoso y precioso»?", "3", "Son tres palabras de significado parecido: bello, hermoso y precioso.")]),
  [E("Para el cartel de una biblioteca, ¿qué conviene más: «Silencio, por favor» o «Cállense, chicos»?", "Silencio, por favor", "Es el registro adecuado para un aviso público.")],
  [E("¿Qué es una colocación: una palabra o una combinación habitual de palabras?", "Una combinación habitual de palabras", "Por ejemplo, clima cálido."),
   E("Si dos palabras tienen significado cercano pero distinto matiz, ¿son sinónimos exactos?", "No", "Casi nunca son idénticos."),
   E("¿Qué palabra es más formal: «infante» o «chico»?", "Infante", "Es la de registro más formal.")],
  ("Lee: «El domingo hizo calor. Mi hermano abrió la ventana grande y bebió un vaso de agua fría. Después ordenamos la sala, que estaba muy desordenada». Elige tres palabras y escribe un sinónimo para cada una que calce con el contexto. Explica en una frase por qué cada sinónimo sirve.",
   "«Calor» por «temperatura alta», «grande» por «amplia» y «desordenada» por «revuelta». «Amplia» calza con «ventana» porque indica tamaño, y «revuelta» conserva el sentido de poco orden.",
   ["elige tres palabras del texto", "propone sinónimos con el mismo sentido", "justifica con una pista de contexto"], ["tres pares de palabras", "tres justificaciones"], ["escoger un sinónimo de otro sentido", "no justificar"], "Lee tu versión en voz alta; si una palabra suena rara, revisa su combinación habitual."),
  "Busca una oración de un libro o cuaderno y cambia dos palabras por sinónimos que mantengan el sentido.",
  "Escribe una oración con «grave» y otra con «voz grave» y explica la diferencia de sentido.")

L(OA17, 4,
  MAT,
  "Aprenderé a usar hiperónimos (palabras más generales) para nombrar de nuevo un referente y a construir una cadena de palabras que van de lo más específico a lo más general.",
  ["Sé sustituir con sinónimos.", "Sé agrupar elementos por categoría."],
  ["Un hiperónimo es una palabra cuyo significado incluye el de otras más específicas. «Animal» es hiperónimo de «perro», «gato» y «caballo». Esas palabras específicas se llaman hipónimos. Así, «herramienta» es hiperónimo de «martillo», «serrucho» y «alicate».",
   "Los hiperónimos sirven para retomar un referente sin repetirlo: «Los pinos y los robles crecieron en el cerro. Estos árboles dieron sombra». Además se pueden encadenar de lo más específico a lo más general: perro, mamífero, animal, ser vivo. Cada eslabón incluye al anterior.",
   "Usa el hiperónimo con medida. Si es demasiado general («cosa», «algo»), el lector pierde el referente. Conviene el término más cercano que aún abarque todos los casos del texto. Un recurso útil es el demostrativo: «estos árboles», «esas herramientas». Ayuda a mostrar que se retoma lo ya dicho."],
  [("hiperónimo", "palabra más general que incluye a otras, como «animal»"), ("hipónimo", "palabra más específica incluida en un hiperónimo, como «perro»"), ("cadena léxica", "serie de palabras que nombran el mismo referente en un texto"), ("categoría", "grupo de elementos que comparten una característica")],
  [("Hallar el hiperónimo", "¿Qué hiperónimo agrupa «martillo», «serrucho» y «alicate»?",
    ["Veo qué tienen en común: sirven para trabajar.", "Todos son objetos para hacer tareas.", "El nombre general es «herramientas»."],
    "Herramientas"),
   ("Ordenar una cadena", "Ordena de lo más específico a lo más general: animal, perro, mamífero.",
    ["Perro es lo más particular.", "Mamífero incluye al perro.", "Animal incluye a los mamíferos."],
    "Perro, mamífero, animal")],
  [("Usar un hiperónimo tan general que se pierde el referente.", "Se escribe «las cosas» en vez de «las herramientas».", "Escoge el hiperónimo más cercano que aún incluya todos los casos."),
   ("Confundir el hiperónimo con un hipónimo.", "Se piensa que «perro» incluye a «animal».", "El hiperónimo es el que incluye: «animal» incluye al «perro».")],
  ([E("¿Cuál es el hiperónimo de «violín», «flauta» y «tambor»?", "Instrumentos musicales", "Es la categoría que los incluye a todos."),
    E("¿Cuál es el hiperónimo de «Chile», «Perú» y «Bolivia»?", "Países", "Los tres son países."),
    E("¿Cuál de estas dos palabras es el hipónimo: «silla» o «mueble»?", "Silla", "La silla es un tipo de mueble.")],
   [E("«Los pinos y los robles crecieron en el cerro. Estos ___ dieron sombra.» ¿Qué palabra completa: «árboles» o «hojas»?", "árboles", "Incluye a pinos y robles."),
    E("¿Cuál NO es un hipónimo de «fruta»: «manzana», «pera» o «martillo»?", "Martillo", "Es una herramienta, no una fruta."),
    E("Ordena de lo más general a lo más específico: perro, animal, mamífero.", "Animal, mamífero, perro", "Cada palabra incluye a la siguiente.")],
   [E("En «El lápiz, la goma y la regla estaban sobre la mesa. Los útiles escolares eran nuevos.», ¿qué palabra es el hiperónimo?", "útiles escolares", "Reúne al lápiz, la goma y la regla."),
    E("¿Cuántos hipónimos de «herramienta» aparecen en «El martillo, el serrucho y el alicate estaban sobre el banco»?", "3", "Son martillo, serrucho y alicate."),
    E("¿Qué palabra intrusa hay en «mesa, silla, cama, lápiz» para la categoría «muebles»?", "Lápiz", "No es un mueble, es un útil escolar.")],
   [E("Un texto dice «Los jotes, los cóndores y las águilas vuelan alto. Las aves buscan alimento». ¿«Las aves» es un hiperónimo adecuado?", "Sí", "Incluye a jotes, cóndores y águilas."),
    E("En «Pedro llevó pan, queso y fruta. Las cosas eran para el picnic», ¿qué hiperónimo más preciso reemplaza a «cosas»?", "Alimentos", "«Cosas» es demasiado general; «alimentos» agrupa pan, queso y fruta.")],
   [E("En la cadena roble, árbol, planta, ser vivo, ¿cuántos eslabones incluyen al roble?", "3", "Árbol, planta y ser vivo."),
    E("«El zorro, el puma y el guanaco viven en la Patagonia. Estos mamíferos resisten el frío». ¿Es correcto llamarlos «mamíferos» si los tres amamantan a sus crías?", "Sí", "Los tres son mamíferos, por lo que el hiperónimo es correcto.")]),
  [E("En una guía de reciclaje: «Latas, botellas plásticas y cajas de cartón van al contenedor». ¿Qué hiperónimo usarías para retomarlas: «residuos reciclables» o «cosas»?", "Residuos reciclables", "Es el término más cercano que las incluye a todas.")],
  [E("¿Cómo se llama la palabra más general que incluye a otras?", "Hiperónimo", "Incluye el significado de las palabras específicas."),
   E("¿«Gato» es hiperónimo o hipónimo de «animal»?", "Hipónimo", "Es un caso específico de animal."),
   E("¿Por qué «cosa» suele ser un mal hiperónimo?", "Porque es tan general que se pierde el referente", "No dice qué categoría concreta se retoma.")],
  ("Completa con hiperónimos precisos: «Sandra compró manzanas, peras y plátanos. Las ___ estaban maduras.» «En el taller había alicates, destornilladores y llaves. Las ___ eran nuevas». «En la plaza jugaban Pía, Raúl y Dani. Los ___ se divertían». Luego escribe una cadena de cuatro eslabones desde «gaviota» hasta una palabra general.",
   "Las frutas; Las herramientas; Los amigos (o los jugadores). Cadena: gaviota, ave, animal, ser vivo.",
   ["usa hiperónimos que incluyen a todos los casos", "evita palabras vacías como cosa", "arma una cadena ordenada"], ["tres completaciones", "cadena de cuatro palabras"], ["usar «cosas» en todo", "invertir el orden de la cadena"], "Pide a alguien que verifique que cada palabra de la cadena incluya a la anterior."),
  "Elige tres objetos de tu pieza y escribe el hiperónimo que los agrupa.",
  "Construye dos cadenas de cuatro palabras, una de animales y otra de objetos, de lo específico a lo general.")

L(OA17, 5,
  MAT,
  "Aprenderé a revisar un texto con una lista de comprobación para encontrar repeticiones que sobran y expresiones ambiguas, y a reescribirlo con claridad.",
  ["Sé usar sinónimos e hiperónimos.", "Reconozco qué es la ambigüedad."],
  ["Revisar la cohesión significa comprobar que el lector siga sin esfuerzo a cada referente de un texto. Una lista breve ayuda: 1) ¿Encuentro todos los lugares donde se nombra cada referente? 2) ¿Hay repeticiones que sobran? 3) ¿Cada sustitución nombra lo mismo que la original? 4) ¿Alguna expresión puede entenderse de dos maneras?",
   "La ambigüedad suele aparecer cuando hay dos referentes posibles. En «Valentina le dijo a Camila que su informe estaba listo», «su» puede ser de Valentina o de Camila. Para resolverlo se repite el nombre o se agrega un dato: «Valentina le dijo a Camila que el informe de Camila estaba listo».",
   "Al revisar, cambia solo lo necesario. Si un texto ya se entiende, no lo reescribas por completo. Al terminar, léelo en voz alta y pregunta a otra persona a qué se refiere cada expresión dudosa. Si responde igual que tú, el texto está claro."],
  [("lista de comprobación", "serie de preguntas para revisar un texto paso a paso"), ("ambigüedad", "posibilidad de entender una expresión de dos maneras"), ("revisar", "leer de nuevo un escrito para mejorarlo"), ("desambiguar", "agregar un dato para que solo haya una lectura posible")],
  [("Detectar la ambigüedad", "En «Tomás le dijo a Iván que su bicicleta estaba rota», ¿qué es ambiguo?",
    ["Hay dos personas: Tomás e Iván.", "«Su» puede ser de cualquiera.", "La expresión ambigua es «su»."],
    "«su bicicleta»: no se sabe de quién es"),
   ("Corregir con claridad", "Corrige: «Ana habló con Rosa y ella ganó».",
    ["No se sabe quién es «ella».", "Repito el nombre para decidir.", "Escribo «Ana habló con Rosa y Rosa ganó» (o «y Ana ganó»)."],
    "Ana habló con Rosa y Rosa ganó")],
  [("Corregir cambiando todas las palabras.", "Se piensa que reescribir mucho es corregir mejor.", "Cambia solo lo que genera repetición excesiva o confusión."),
   ("Creer que si uno entiende, todos entienden.", "Se revisa sin la mirada de otro lector.", "Pide que otra persona diga a qué se refiere cada expresión dudosa.")],
  ([E("En «Luis llamó a Paula y le contó que había ganado», ¿hay dos personas posibles para «había ganado»?", "Sí", "Puede ser Luis o Paula."),
    E("En «El museo abre a las 9. El museo cierra a las 17», ¿cuántas veces se repite «El museo»?", "2", "Aparece una vez en cada oración."),
    E("¿Cómo se llama agregar un dato para que haya una sola lectura posible?", "Desambiguar", "Elimina la duda del lector.")],
   [E("«Marta dijo a Elena que su tarea estaba bien.» ¿Qué palabra genera la duda?", "su", "Puede ser la tarea de Marta o la de Elena."),
    E("¿Cuál versión es clara: «Vi a Pedro y a Juan. Pedro dijo que Juan estaba cansado» o «Vi a Pedro y a Juan. Él dijo que estaba cansado»?", "La primera", "La segunda no aclara quién habló ni quién está cansado."),
    E("«La directora saludó a la profesora. La profesora sonrió.» ¿Es necesaria la repetición de «La profesora»?", "Sí", "Evita confundirla con la directora.")],
   [E("Corrige la ambigüedad: «Carlos vio a Diego y le pidió su cuaderno». ¿Qué cambio sirve: «y le pidió el cuaderno de Diego» o «y le pidió algo»?", "y le pidió el cuaderno de Diego", "Aclara de quién es el cuaderno."),
    E("En un texto de 4 oraciones, «la feria» aparece 4 veces seguidas y no hay otro referente. ¿Qué conviene: reemplazar 2 por sinónimos o repetir las 4?", "Reemplazar 2 por sinónimos", "Alivia la repetición sin confundir."),
    E("«Mi tía y mi madre viajaron. Ella volvió ayer.» ¿Es ambiguo «Ella»?", "Sí", "Puede ser la tía o la madre.")],
   [E("Dos estudiantes corrigen: «Sara habló con Julia y ella llegó tarde». Una escribe «y Julia llegó tarde»; otra, «y la joven llegó tarde». ¿Quién desambiguó mejor?", "La primera", "«La joven» podría ser Sara o Julia."),
    E("«El equipo de Pía y el equipo de Beto jugaron. El equipo ganó 3-1.» ¿Qué dato falta?", "Cuál equipo ganó", "No se sabe cuál de los dos ganó.")],
   [E("«Gaspar le contó a Hugo que lo habían elegido.» ¿Se sabe quién fue elegido?", "No", "«Lo» puede ser Gaspar o Hugo."),
    E("«Rocío y Ema pintaron el cuarto. Rocío dijo que le gustaba el color de Ema.» ¿Se entiende de quién es el color?", "Sí", "Dice que es el color de Ema.")]),
  [E("Revisas el aviso del curso: «Josefa invitó a Nicole a su cumpleaños. Ella llevará la torta». ¿Quién llevará la torta?", "No se puede saber", "«Ella» puede referirse a Josefa o a Nicole.")],
  [E("¿Qué pregunta de la lista de comprobación busca ambigüedades?", "¿Alguna expresión puede entenderse de dos maneras?", "Esa pregunta revisa dobles lecturas."),
   E("Si el texto ya se entiende, ¿conviene reescribirlo por completo?", "No", "Se cambia solo lo necesario."),
   E("¿Qué puedes pedir a otra persona para comprobar la claridad?", "Que diga a qué se refiere cada expresión dudosa", "Si coincide contigo, el texto está claro.")],
  ("Revisa este texto con la lista de comprobación y reescríbelo: «Fabiola y Ruth armaron un robot. Fabiola probó el robot. El robot se movió. Ella dijo que el robot le gustaba. Ruth anotó el resultado y ella lo guardó.» Marca las repeticiones que sobran y las dos expresiones ambiguas.",
   "Repeticiones que sobran: «el robot» en la segunda, tercera y cuarta oración. Ambiguas: «Ella dijo...» y «ella lo guardó». Versión: «Fabiola y Ruth armaron un robot. Fabiola lo probó y el robot se movió. Fabiola dijo que le gustaba. Ruth anotó el resultado y lo guardó en su carpeta».",
   ["identifica repeticiones excesivas", "identifica ambigüedades", "reescribe sin crear nuevas confusiones"], ["texto con marcas", "versión final"], ["cambiar «Ella» por «la niña»", "reescribir todo"], "Léelo a otra persona y pídele que diga quién hace cada acción."),
  "Revisa un mensaje que hayas escrito esta semana y busca una repetición que sobre o una expresión ambigua.",
  "Escribe tres oraciones con una ambigüedad a propósito y luego su versión corregida.")
